def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def positions_from(obj):
        out = []
        if isinstance(obj, dict):
            for v in obj.values():
                p = as_pos(v)
                if p is not None:
                    out.append(p)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = as_pos(v)
                if p is not None:
                    out.append(p)
        return out

    env = observation.get("environment_name", "")
    sx, sy = observation.get("self_position", (0, 0))
    opp = observation.get("opponent_position", (sx, sy))
    ox, oy = opp if isinstance(opp, (list, tuple)) and len(opp) >= 2 else (sx, sy)
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, (ox, oy))
            if best is None or d > best:
                best = d
                target = c
        if target is None:
            return [0, 0]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "frontier_cells"):
            targets = positions_from(observation.get(key))
            if targets:
                break
        if not targets:
            # drift toward opponent or center
            if gw and gh:
                return [step_toward(sx, gw // 2), step_toward(sy, gh // 2)]
            return [step_toward(sx, ox), step_toward(sy, oy)]
        target = min(targets, key=lambda p: manhattan(p, (sx, sy)))
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    # resource_collection and fallback
    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "food"):
        resources = positions_from(observation.get(key))
        if resources:
            break

    if resources:
        target = min(resources, key=lambda p: manhattan(p, (sx, sy)))
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    # secondary fallback: move away from opponent if close, else toward center
    if manhattan((sx, sy), (ox, oy)) <= 2:
        return [step_toward(ox, sx), step_toward(oy, sy)]
    if gw and gh:
        return [step_toward(sx, gw // 2), step_toward(sy, gh // 2)]
    return [0, 0]

